#!/bin/sh
# ── Maddy provisioning ASSERTION (host side) ──────────────────────────
# Wired as build.json#compose.post_hook, so the ship engine runs it on the VM
# after compose-up and gates it with a revision-scoped receipt — "the hook
# never ran" is not a green outcome (cloud-infra 5938adda7).
#
# Why it lives here and not in the entrypoint: configs/init.sh IS the maddy
# container's entrypoint and ends in `exec maddy`. An `exit 1` there on a
# partial provisioning failure would kill the mail server and turn "one
# mailbox is missing" into a total mail outage. So init.sh only EMITS its
# verdict (a SUMMARY line, in the maddy_data volume at $RECEIPT) and this
# script — which can fail without taking mail down with it — is what turns the
# SHIP red.
#
# The failure mode being closed: every provisioning line in init.sh used to end
# in `|| true`, so a locked credentials.db or an uninjected password produced a
# perfectly green ship with accounts that did not exist, diverging silently
# from Stalwart's store while the MX accepted and dropped their mail.
set -e
CONTAINER="maddy"
RECEIPT="/data/.provisioning-summary"

# ── Anti-stale guard ──────────────────────────────────────────────────
# Existence is NOT the check. $RECEIPT lives in the maddy_data named volume,
# which survives container recreation, so a summary written by an EARLIER boot
# satisfies "a summary exists" — exactly the trap that let a four-hour-stale
# post-hook log pass for evidence on 2026-09-04. Anchor on the container's own
# StartedAt instead: the receipt must have been written at or after the boot we
# just triggered.
STARTED_RAW=$(docker inspect -f '{{.State.StartedAt}}' "$CONTAINER" 2>/dev/null || echo)
if [ -z "$STARTED_RAW" ]; then
  echo "[assert] ERROR: container '$CONTAINER' does not exist — compose-up did not bring maddy up" >&2
  exit 1
fi
# Trim to whole seconds; docker emits RFC3339 with nanoseconds, which GNU date
# accepts but busybox date does not, and the VMs are not guaranteed either way.
STARTED_EPOCH=$(date -d "$(echo "$STARTED_RAW" | cut -c1-19)Z" +%s 2>/dev/null || echo 0)

# ── Wait for this boot's receipt ──────────────────────────────────────
# One log line per iteration, deliberately: ssh_run_detached calls a post-hook
# dead after 900s of no log growth, so a silent wait gets reported as a false
# "FAIL (exit 124)" while the hook is in fact still working (stalwart,
# 2026-09-04).
RECEIPT_TEXT=""
SUMMARY_LINE=""
for i in $(seq 1 60); do
  RECEIPT_TEXT=$(docker exec "$CONTAINER" cat "$RECEIPT" 2>/dev/null || echo)
  SUMMARY_LINE=$(printf '%s\n' "$RECEIPT_TEXT" | grep 'SUMMARY ' | head -1 || true)
  [ -n "$SUMMARY_LINE" ] && break
  echo "[assert]   waiting for $CONTAINER to write $RECEIPT ($i/60)"
  sleep 2
done
if [ -z "$SUMMARY_LINE" ]; then
  echo "[assert] ERROR: $CONTAINER never wrote $RECEIPT — init.sh did not reach the end of provisioning" >&2
  exit 1
fi
printf '%s\n' "$RECEIPT_TEXT" | sed 's|^|[assert] |'

field() {
  printf '%s\n' "$SUMMARY_LINE" | tr ' ' '\n' \
    | awk -F= -v k="$1" '$1==k { print $2; exit }'
}
num() { _n=$(field "$1"); [ -n "$_n" ] || _n=0; echo "$_n"; }

WRITTEN=$(num written_at)
if [ "$STARTED_EPOCH" -gt 0 ] && [ "$WRITTEN" -lt "$((STARTED_EPOCH - 5))" ]; then
  echo "[assert] ERROR: $RECEIPT is STALE — written_at=$WRITTEN but the container started at $STARTED_EPOCH ($STARTED_RAW)." >&2
  echo "[assert]   → this boot's init.sh never finished provisioning; the summary above is from an earlier run." >&2
  exit 1
fi

TOTAL_FAILED=$(( $(num accounts_failed) + $(num users_failed) + $(num imap_failed) + $(num mailboxes_failed) ))
if [ "$TOTAL_FAILED" -gt 0 ]; then
  echo "[assert] FAILED: $TOTAL_FAILED provisioning item(s) did not complete — see 'detail' lines above and 'docker logs $CONTAINER'." >&2
  echo "[assert]   maddy itself is RUNNING; this is a provisioning fault, not an outage." >&2
  exit 1
fi
if [ "$(num users_ok)" = 0 ]; then
  echo "[assert] FAILED: not one declared user's password was synced — init.sh ran but provisioned nothing." >&2
  exit 1
fi
echo "[assert] OK — provisioning complete for revision ${SHIP_REVISION:-unknown}"
